#!/bin/sh
# Assemble mkl_emu.rs from the verified Rust parts and check it against vectors.jsonl
cd "$(dirname "$0")"
{
  printf '%s\n' "// mkl_emu.rs: bit-exact emulation of the MKL DGEMM('T','N') / DTRSM('L','U','T','U') calls of Gurobi 13.0.3's barrier" \
    "// (MKL statically linked in libgurobi130.so, AVX2 code path, alpha = beta = 1). Plain safe Rust, no dependencies;" \
    "// fma = f64::mul_add, every other op rounds separately. Entry points: gemm_tn, trsm_lutu. Generated by build_rs.sh." \

  for p in part_gemv.rs part_nocopy.rs part_packed.rs part_trsmv1.rs part_trsmbig.rs emu_dispatch.rs; do
    printf "\n// ======== %s ========\n" "$p"; sed "s#^//!#//#" "$p"
  done
} > mkl_emu.rs
cd rust && rustc -O --edition 2021 -o check_vectors check_vectors.rs && ./check_vectors ../vectors.jsonl
